INSERT INTO repo_cf_values (cf_value_id, education_level, sub_heading, text, status) VALUES ('CFV_SDG02_TVET_002', 'TVET', 'Sustainability and social responsibility', 'Promote health and nutrition within the workplace and community, supporting a culture of wellbeing and informed food choices.', 'Active'), ('CFV_SDG02_TVET_003', 'TVET', 'Rural empowerment and innovation', 'Cultivate an entrepreneurial mindset, seeing opportunities in food production, processing and marketing that contribute to rural development and self-reliance.', 'Active'), ('CFV_SDG02_TVET_004', 'TVET', 'Rural empowerment and innovation', 'Value the importance of food tourism and artisanal food initiatives in enhancing community identity and economic opportunity.', 'Active'), ('CFV_SDG02_TVET_005', 'TVET', 'Equity and advocacy', 'Show dedication to equitable food access, recognising the social, economic and environmental significance of food security for vulnerable populations.', 'Active'), ('CFV_SDG02_TVET_006', 'TVET', 'Equity and advocacy', 'Advocate for inclusive agricultural policies and innovations that respond to local needs and respect indigenous knowledge and sustainable practices.', 'Active'), ('CFV_SDG02_TVET_007', 'TVET', 'Adaptability and leadership', 'Embrace innovation, technology and lifelong learning to remain responsive to shifts in agriculture, food markets and global challenges.', 'Active'), ('CFV_SDG02_TVET_008', 'TVET', 'Adaptability and leadership', 'Take initiative to lead or support community efforts that advance food system resilience, nutrition security and sustainable development.', 'Active'), ('CFV_SDG02_TER_001', 'Tertiary education', 'Sustainability and responsibility', 'Demonstrate a strong commitment to sustainable food systems that prioritise environmental conservation, ethical food production and social equity.', 'Active'), ('CFV_SDG02_TER_002', 'Tertiary education', 'Sustainability and responsibility', 'Show leadership in promoting responsible consumption, reducing food waste and advocating for fair and resilient food systems.', 'Active'), ('CFV_SDG02_TER_003', 'Tertiary education', 'Equity and cultural respect', 'Respect diverse dietary practices, cultural food traditions and indigenous knowledge as vital elements of sustainable development and inclusive education.', 'Active'), ('CFV_SDG02_TER_004', 'Tertiary education', 'Equity and cultural respect', 'Champion equitable access to nutritious food, especially for marginalised or vulnerable populations.', 'Active'), ('CFV_SDG02_TER_005', 'Tertiary education', 'Innovation and entrepreneurship', 'Exhibit motivation to explore new opportunities in agriculture, food tourism and artisanal production that support local economies and sustainable practices.', 'Active'), ('CFV_SDG02_TER_006', 'Tertiary education', 'Innovation and entrepreneurship', 'Display adaptability and innovation in response to shifting environmental conditions, technological changes and evolving food systems.', 'Active'), ('CFV_SDG02_TER_007', 'Tertiary education', 'Advocacy and global citizenship', 'Embrace a global perspective on food security, recognising interdependence across nations and sectors.', 'Active'), ('CFV_SDG02_TER_008', 'Tertiary education', 'Advocacy and global citizenship', 'Commit to taking informed action on hunger, malnutrition and food justice as agents of change within academic, professional and civic spaces.', 'Active'), ('CFV_SDG02_ADULT_001', 'Adult education', 'Community empowerment and collaboration', 'Embrace a collaborative mindset by supporting others and working collectively to strengthen local food security and agricultural livelihoods.', 'Active'), ('CFV_SDG02_ADULT_002', 'Adult education', 'Community empowerment and collaboration', 'Promote women’s leadership and participation in farming groups, co-operatives and food governance structures.', 'Active'), ('CFV_SDG02_ADULT_003', 'Adult education', 'Responsibility and stewardship', 'Take responsibility for sustainable land use, 